// Private fixture on stdin. Use the built Web application and the real loopback
// user router. No responses are intercepted or generated by the browser test.
import { chromium } from '@playwright/test';
import { preview } from 'vite';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root=fileURLToPath(new URL('../',import.meta.url));
const tls=resolve(root,'../../.local/tls');
let input='';
for await (const chunk of process.stdin) input+=chunk;
const f=JSON.parse(input);
const upstream=new URL(f.api);
if(upstream.protocol!=='http:'||upstream.hostname!=='127.0.0.1'||!upstream.port ||
    f.origin!=='https://127.0.0.1:43122' || typeof f.token!=='string')throw Error('Expected a private loopback user fixture');
const server=await preview({root,configFile:false,logLevel:'silent',preview:{host:'127.0.0.1',port:43122,strictPort:true,
  https:{key:readFileSync(resolve(tls,'key.pem')),cert:readFileSync(resolve(tls,'cert.pem'))},
  proxy:{'/api/v1/':{target:upstream.origin,changeOrigin:false}}}});
let browser;
try {
  browser=await chromium.launch({channel:'chrome',headless:true});
  const context=await browser.newContext({baseURL:f.origin,ignoreHTTPSErrors:true,viewport:{width:1280,height:960}});
  await context.addCookies([{name:'__Host-orange-user',value:f.token,url:f.origin,secure:true,httpOnly:true,sameSite:'Lax'}]);
  const page=await context.newPage();
  page.setDefaultTimeout(15000);
  let writes=0;
  page.on('request',r=>{if(r.method()!=='GET'&&new URL(r.url()).pathname.startsWith('/api/v1/'))writes++;});
  await page.goto('/support');
  await page.getByRole('checkbox').filter({visible:true}).first().waitFor();
  await page.getByRole('checkbox',{name:new RegExp(f.artifact)}).check();
  await page.getByLabel('关联工单').fill('browser-owned-support');
  await page.getByLabel('支持用途').fill('仅授权本次诊断文件');
  const created=page.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname==='/api/v1/account/support-authorizations');
  await page.getByRole('button',{name:'确认授权所选版本'}).click();
  const response=await created, receipt=await response.json();
  if(response.status()!==201||receipt.subject_user_id!==f.user||receipt.resources.length!==1||receipt.resources[0].version_id!==f.version)throw Error('Incorrect consent receipt');
  await page.getByRole('heading',{name:'browser-owned-support · 有效',exact:true}).waitFor();
  const revoked=page.waitForResponse(r=>r.request().method()==='DELETE'&&new URL(r.url()).pathname.endsWith('/'+receipt.authorization_id));
  await page.getByRole('button',{name:'撤销授权',exact:true}).click();
  const end=await revoked;
  if(end.status()!==200||(await end.json()).status!=='revoked')throw Error('Revocation not committed');
  await page.reload();
  await page.getByRole('heading',{name:'browser-owned-support · 已撤销',exact:true}).waitFor();
  if(await page.getByRole('button',{name:'撤销授权',exact:true}).count()||writes!==2)throw Error('Unexpected effects after session reload');
  await page.screenshot({path:f.screenshot,fullPage:true});
  process.stdout.write(JSON.stringify({authorization_id:receipt.authorization_id,mutations:writes,revoked_after_reload:true})+'\n');
} finally {
  if(browser)await browser.close();
  await server.close();
}
